// The generator and drift check, scripts/sync-persona-pipeline.mjs (ADR-0066
// Decision 4): generated files, the ownership ledger, the refusals, and the
// PC1 acceptance — the check fails on a hand edit to a generated copy and
// --write restores it.

import { describe, it } from 'node:test';
import { deepStrictEqual, match, ok, strictEqual } from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import {
  chmodSync, cpSync, existsSync, lstatSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, symlinkSync, writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { runSync } from '../../scripts/sync-persona-pipeline.mjs';
import { MANIFEST, REPO_ROOT } from './_personas.mjs';

const SCRIPT = join(REPO_ROOT, 'scripts/sync-persona-pipeline.mjs');
const FIXTURE = join(REPO_ROOT, 'tests/persona-pipeline/fixtures/regions');

function fixtureCopy() {
  const dir = mkdtempSync(join(tmpdir(), 'pp-sync-'));
  cpSync(FIXTURE, dir, { recursive: true });
  cpSync(join(REPO_ROOT, 'persona-pipeline/persona.schema.json'), join(dir, 'persona-pipeline/persona.schema.json'));
  chmodSync(join(dir, 'persona-pipeline/files/scripts/tool.mjs'), 0o755);
  return dir;
}

async function sync(root, opts = {}) {
  let out = '';
  let err = '';
  const code = await runSync({
    root,
    out: { write: (s) => { out += s; return true; } },
    err: { write: (s) => { err += s; return true; } },
    ...opts,
  });
  return { code, out, err };
}

async function written(root) {
  const r = await sync(root, { write: true });
  strictEqual(r.code, 0, r.err);
  return r;
}

const read = (root, rel) => readFileSync(join(root, rel), 'utf8');
const ledger = (root) => JSON.parse(read(root, 'persona-pipeline/owned.json'));
function editManifest(root, edit) {
  const path = join(root, 'persona-pipeline/manifest.json');
  const m = JSON.parse(readFileSync(path, 'utf8'));
  edit(m);
  writeFileSync(path, JSON.stringify(m, null, 2));
}
function snapshotTree(root, rels) {
  return Object.fromEntries(rels.map((rel) => [rel, existsSync(join(root, rel)) ? read(root, rel) : null]));
}

describe('generation', () => {
  it('writes each unit with the notice after the shebang, JSON without one, the canonical mode, and a ledger', async () => {
    const root = fixtureCopy();
    await written(root);
    const tool = read(root, 'plugins/alpha/scripts/tool.mjs');
    ok(tool.startsWith('#!/usr/bin/env node\n// GENERATED by persona-pipeline — do not edit this copy.\n'));
    match(tool, /\/\/ Source: persona-pipeline\/files\/scripts\/tool\.mjs\. Edit the source, then run\n\/\/ `npm run sync:persona-pipeline -- --write` \(ADR-0066\)\.\n/);
    strictEqual(read(root, 'plugins/beta/scripts/tool.mjs'), tool, 'every persona runs the same bytes');
    ok(statSync(join(root, 'plugins/beta/scripts/tool.mjs')).mode & 0o100, 'the executable bit is kept');
    strictEqual(read(root, 'plugins/alpha/data/config.json'), read(root, 'persona-pipeline/files/data/config.json'));
    ok(!existsSync(join(root, 'plugins/beta/data/config.json')), 'a unit reaches only the personas it enrolls');
    deepStrictEqual(ledger(root).owned, {
      alpha: ['data/config.json', 'scripts/tool.mjs'],
      beta: ['scripts/tool.mjs'],
    });
    strictEqual((await sync(root)).code, 0);
  });

  it('is idempotent: a second write changes no byte', async () => {
    const root = fixtureCopy();
    await written(root);
    const rels = ['plugins/alpha/scripts/tool.mjs', 'plugins/alpha/commands/run.md', 'persona-pipeline/owned.json'];
    const before = snapshotTree(root, rels);
    await written(root);
    deepStrictEqual(snapshotTree(root, rels), before);
  });

  it('reports a mode mismatch and the write restores the mode', async () => {
    const root = fixtureCopy();
    await written(root);
    chmodSync(join(root, 'plugins/alpha/scripts/tool.mjs'), 0o644);
    const r = await sync(root);
    strictEqual(r.code, 1);
    match(r.err, /plugins\/alpha\/scripts\/tool\.mjs: mode differs \(expected executable\)/);
    await written(root);
    ok(statSync(join(root, 'plugins/alpha/scripts/tool.mjs')).mode & 0o100);
  });

  it('repairs a partially written tree on rerun', async () => {
    const root = fixtureCopy();
    await written(root);
    // An interrupted write: the ledger already owns the outputs, one is missing, one is stale.
    writeFileSync(join(root, 'plugins/beta/scripts/tool.mjs'), '#!/usr/bin/env node\n// GENERATED by persona-pipeline — half written\n');
    rmSync(join(root, 'plugins/alpha/data/config.json'));
    strictEqual((await sync(root)).code, 1);
    await written(root);
    strictEqual((await sync(root)).code, 0);
  });
});

describe('owned outputs and the ledger', () => {
  it('a renamed destination: the old output is reported, then deleted by the write', async () => {
    const root = fixtureCopy();
    await written(root);
    editManifest(root, (m) => { m.units[0].dest = 'scripts/tool-renamed.mjs'; m.units[0].source = 'files/scripts/tool.mjs'; });
    const r = await sync(root);
    strictEqual(r.code, 1);
    match(r.err, /plugins\/alpha\/scripts\/tool\.mjs: owned output the manifest no longer generates/);
    await written(root);
    ok(!existsSync(join(root, 'plugins/alpha/scripts/tool.mjs')));
    ok(existsSync(join(root, 'plugins/alpha/scripts/tool-renamed.mjs')));
    strictEqual((await sync(root)).code, 0);
  });

  it('a removed unit and an unenrolled persona: JSON outputs (no notice) included', async () => {
    const root = fixtureCopy();
    await written(root);
    editManifest(root, (m) => { m.units = m.units.filter((u) => u.id !== 'config'); });
    // The canonical source stays on disk, so the check also reports it unreferenced; move it aside.
    writeFileSync(join(root, 'persona-pipeline/files/data/config.json'), '');
    const r0 = await sync(root);
    match(r0.err, /persona-pipeline\/files\/data\/config\.json is not a unit of the manifest/);
    editManifest(root, (m) => { m.units.push({ id: 'config', source: 'files/data/config.json', dest: 'data/config.json', personas: ['beta'], requires: [] }); });
    const r = await sync(root);
    strictEqual(r.code, 1);
    match(r.err, /plugins\/alpha\/data\/config\.json: owned output the manifest no longer generates/);
    await written(root);
    ok(!existsSync(join(root, 'plugins/alpha/data/config.json')), 'the unenrolled JSON output is deleted');
    ok(existsSync(join(root, 'plugins/beta/data/config.json')));
    deepStrictEqual(ledger(root).owned.alpha, ['scripts/tool.mjs']);
  });

  it('a ledger that disagrees with the generated set fails the check', async () => {
    const root = fixtureCopy();
    await written(root);
    const l = ledger(root);
    l.owned.beta = [];
    writeFileSync(join(root, 'persona-pipeline/owned.json'), JSON.stringify(l));
    const r = await sync(root);
    strictEqual(r.code, 1);
    match(r.err, /owned\.json does not list plugins\/beta\/scripts\/tool\.mjs/);
  });
});

describe('refusals (write mode changes nothing)', () => {
  const rels = ['plugins/alpha/scripts/tool.mjs', 'plugins/beta/scripts/tool.mjs', 'plugins/alpha/data/config.json',
    'plugins/alpha/commands/run.md', 'plugins/beta/commands/run.md', 'persona-pipeline/owned.json'];

  const cases = {
    'two units with one destination': [(root) => editManifest(root, (m) => { m.units.push({ ...m.units[0], id: 'tool-2' }); }), /generated by two units/],
    'overlapping destinations': [(root) => editManifest(root, (m) => { m.units.push({ id: 'nest', source: 'files/data/config.json', dest: 'scripts/tool.mjs/inner.json', personas: ['alpha'], requires: [] }); }), /destinations overlap|unit|generated by two units/],
    'a traversal destination': [(root) => editManifest(root, (m) => { m.units[0].dest = '../escape.mjs'; }), /path traversal/],
    'an absolute destination': [(root) => editManifest(root, (m) => { m.units[0].dest = '/tmp/escape.mjs'; }), /absolute path/],
    'a destination whose parent is a symlink out of the plugin': [(root) => {
      const outside = mkdtempSync(join(tmpdir(), 'pp-outside-'));
      symlinkSync(outside, join(root, 'plugins/alpha/scripts'));
    }, /plugins\/alpha\/scripts is a symlink/],
    'a file it does not own (present, not in the ledger, no notice, different)': [(root) => {
      mkdirSync(join(root, 'plugins/beta/scripts'), { recursive: true });
      writeFileSync(join(root, 'plugins/beta/scripts/tool.mjs'), '// hand-maintained\n');
    }, /plugins\/beta\/scripts\/tool\.mjs: refused — present, not in owned\.json, without the generated notice/],
    'a render failure on a later unit': [(root) => editManifest(root, (m) => { m.units[1].source = 'files/data/missing.json'; }), /canonical source persona-pipeline\/files\/data\/missing\.json is unreadable/],
    'a canonical file no unit references': [(root) => writeFileSync(join(root, 'persona-pipeline/files/scripts/stray.mjs'), ''), /files\/scripts\/stray\.mjs is not a unit of the manifest/],
    'an invalid manifest': [(root) => editManifest(root, (m) => { m.units[0].personas = ['gamma']; }), /persona "gamma" is not in manifest\.personas/],
  };
  for (const [what, [arrange, re]] of Object.entries(cases)) {
    it(`refuses ${what}`, async () => {
      const root = fixtureCopy();
      arrange(root);
      const before = snapshotTree(root, rels);
      const r = await sync(root, { write: true });
      strictEqual(r.code, 1);
      match(r.err, re);
      deepStrictEqual(snapshotTree(root, rels), before, 'a refused write changes nothing');
    });
  }

  it('--adopt takes over a hand copy at a manifest destination, and only there', async () => {
    const root = fixtureCopy();
    mkdirSync(join(root, 'plugins/beta/scripts'), { recursive: true });
    writeFileSync(join(root, 'plugins/beta/scripts/tool.mjs'), '// hand-maintained\n');
    writeFileSync(join(root, 'plugins/beta/scripts/other.mjs'), '// not the pipeline\n');
    const r = await sync(root, { write: true, adopt: true });
    strictEqual(r.code, 0, r.err);
    match(r.out, /plugins\/beta\/scripts\/tool\.mjs: taken over and regenerated/);
    strictEqual(read(root, 'plugins/beta/scripts/tool.mjs'), read(root, 'plugins/alpha/scripts/tool.mjs'));
    strictEqual(read(root, 'plugins/beta/scripts/other.mjs'), '// not the pipeline\n');
  });

  it('the CLI refuses --adopt without --write and an unknown argument', () => {
    let r = spawnSync(process.execPath, [SCRIPT, '--adopt'], { encoding: 'utf8' });
    strictEqual(r.status, 2);
    match(r.stderr, /--adopt only applies with --write/);
    r = spawnSync(process.execPath, [SCRIPT, '--force'], { encoding: 'utf8' });
    strictEqual(r.status, 2);
    match(r.stderr, /unknown argument --force/);
  });
});

describe('review regressions (Codex review of PC1)', () => {
  it('never deletes through a symlinked persona directory, even for a retired persona the ledger still lists', async () => {
    const root = fixtureCopy();
    await written(root);
    const outside = mkdtempSync(join(tmpdir(), 'pp-outside-'));
    mkdirSync(join(outside, 'scripts'));
    writeFileSync(join(outside, 'scripts/tool.mjs'), 'external, not ours\n');
    const l = ledger(root);
    l.owned.gamma = ['scripts/tool.mjs'];
    writeFileSync(join(root, 'persona-pipeline/owned.json'), JSON.stringify(l));
    symlinkSync(outside, join(root, 'plugins/gamma'), 'dir');
    const r = await sync(root, { write: true });
    strictEqual(r.code, 1);
    match(r.err, /plugins\/gamma\/scripts\/tool\.mjs: refused — plugins\/gamma is a symlink/);
    strictEqual(readFileSync(join(outside, 'scripts/tool.mjs'), 'utf8'), 'external, not ours\n');
  });

  it('writes the ledger atomically: a symlinked owned.json is replaced by a file, its target untouched', async () => {
    const root = fixtureCopy();
    await written(root);
    const outside = join(mkdtempSync(join(tmpdir(), 'pp-outside-')), 'owned.json');
    const valid = read(root, 'persona-pipeline/owned.json');
    writeFileSync(outside, valid);
    rmSync(join(root, 'persona-pipeline/owned.json'));
    symlinkSync(outside, join(root, 'persona-pipeline/owned.json'));
    editManifest(root, (m) => { m.units.find((u) => u.id === 'config').personas = ['alpha', 'beta']; });
    await written(root);
    strictEqual(readFileSync(outside, 'utf8'), valid, 'the symlink target is not written through');
    ok(!lstatSync(join(root, 'persona-pipeline/owned.json')).isSymbolicLink());
    deepStrictEqual(ledger(root).owned.beta, ['data/config.json', 'scripts/tool.mjs']);
  });

  it('a whole-file output that becomes a region file is never deleted: it turns authored and leaves the ledger', async () => {
    const root = fixtureCopy();
    await written(root);
    const target = 'plugins/alpha/data/config.json';
    editManifest(root, (m) => {
      m.units = m.units.filter((u) => u.id !== 'config');
      m.regions.push({ id: 'cfg', template: 'templates/intro.md', dest: 'data/config.json', personas: ['alpha'], substitutions: { noun: { field: 'deliverable_noun', context: 'text' } } });
    });
    rmSync(join(root, 'persona-pipeline/files/data/config.json'));
    // Without markers the write refuses and the file stays.
    let r = await sync(root, { write: true });
    strictEqual(r.code, 1);
    match(r.err, /plugins\/alpha\/data\/config\.json: lacks the required region cfg/);
    ok(existsSync(join(root, target)));
    // The author adds the markers next to an authored extension: the write keeps both.
    writeFileSync(join(root, target), 'authored line\n<!-- pipeline:begin cfg -->\n<!-- pipeline:end cfg -->\n');
    r = await sync(root, { write: true });
    strictEqual(r.code, 0, r.err);
    match(read(root, target), /^authored line\n<!-- pipeline:begin cfg -->\nThis runbook produces the alpha deliverable\.\n<!-- pipeline:end cfg -->\n$/);
    deepStrictEqual(ledger(root).owned.alpha, ['scripts/tool.mjs']);
  });

  it('refuses one destination claimed by a whole-file unit and by regions', async () => {
    const root = fixtureCopy();
    editManifest(root, (m) => { m.regions.push({ id: 'twice', template: 'templates/intro.md', dest: 'scripts/tool.mjs', personas: ['alpha'], substitutions: {} }); });
    const r = await sync(root, { write: true });
    strictEqual(r.code, 1);
    match(r.err, /plugins\/alpha\/scripts\/tool\.mjs: both a whole-file unit and generated regions claim it/);
  });

  it('refuses a render that would break the region grammar (an unclosed fence in a template)', async () => {
    const root = fixtureCopy();
    writeFileSync(join(root, 'persona-pipeline/templates/intro.md'), '```bash\necho hi\n');
    const before = read(root, 'plugins/alpha/commands/run.md');
    const r = await sync(root, { write: true });
    strictEqual(r.code, 1);
    match(r.err, /plugins\/alpha\/commands\/run\.md: the rendered regions would break the region grammar/);
    strictEqual(read(root, 'plugins/alpha/commands/run.md'), before);
  });
});

// ---- PC1 acceptance on a copy of the real pipeline ------------------------------

function repoSubsetCopy() {
  const root = mkdtempSync(join(tmpdir(), 'pp-accept-'));
  cpSync(join(REPO_ROOT, 'persona-pipeline'), join(root, 'persona-pipeline'), { recursive: true });
  for (const persona of MANIFEST.personas) {
    cpSync(join(REPO_ROOT, 'plugins', persona), join(root, 'plugins', persona), { recursive: true });
  }
  return root;
}

describe('PC1 acceptance: the drift check fails on a hand edit to a generated copy', () => {
  it('the repository is clean', () => {
    const r = spawnSync(process.execPath, [SCRIPT], { encoding: 'utf8' });
    strictEqual(r.status, 0, r.stderr);
    match(r.stdout, /OK — persona pipeline: \d+ generated file\(s\) across 3 persona\(s\)/);
  });

  for (const [persona, rel] of [['founder', 'scripts/state.mjs'], ['designer', 'scripts/lib/hook-helpers.mjs'], ['engineer', 'adapters/codex/hooks/stop.mjs'], ['engineer', 'hooks/hooks.json']]) {
    it(`plugins/${persona}/${rel}: a hand edit fails the check naming it; --write restores it`, () => {
      const root = repoSubsetCopy();
      const path = join(root, 'plugins', persona, rel);
      const good = readFileSync(path, 'utf8');
      writeFileSync(path, rel.endsWith('.json') ? good.replace('"hooks"', '"hooks" ') : `${good}\n// a hand fix that should have gone to the source\n`);
      const check = spawnSync(process.execPath, [SCRIPT, '--root', root], { encoding: 'utf8' });
      strictEqual(check.status, 1);
      match(check.stderr, new RegExp(`plugins/${persona}/${rel.replace(/[.]/g, '\\.')}: differs from persona-pipeline/files/${rel.replace(/[.]/g, '\\.')}`));
      const write = spawnSync(process.execPath, [SCRIPT, '--root', root, '--write'], { encoding: 'utf8' });
      strictEqual(write.status, 0, write.stderr);
      strictEqual(readFileSync(path, 'utf8'), good);
      strictEqual(spawnSync(process.execPath, [SCRIPT, '--root', root], { encoding: 'utf8' }).status, 0);
    });
  }
});

describe('PC2a acceptance: the drift check fails on a hand edit inside a generated runbook region', () => {
  const cases = [
    ['founder', 'commands/checkpoint.md', '--summary "$SUMMARY"', '--summary "$SUMMARY" --force', 'checkpoint-set'],
    ['designer', 'commands/peer-now.md', 'RUN_RC=$?', 'RUN_RC=0', 'peer-now-dispatch'],
  ];
  for (const [persona, rel, from, to, region] of cases) {
    it(`plugins/${persona}/${rel}: a hand edit in region ${region} fails the check naming it; --write restores it`, () => {
      const root = repoSubsetCopy();
      const path = join(root, 'plugins', persona, rel);
      const good = readFileSync(path, 'utf8');
      strictEqual(good.split(from).length, 2, `${rel} holds the edited text once`);
      writeFileSync(path, good.replace(from, to));
      const check = spawnSync(process.execPath, [SCRIPT, '--root', root], { encoding: 'utf8' });
      strictEqual(check.status, 1);
      match(check.stderr, new RegExp(`plugins/${persona}/${rel.replace(/[.]/g, '\\.')}: region ${region} differs from persona-pipeline/regions/`));
      const write = spawnSync(process.execPath, [SCRIPT, '--root', root, '--write'], { encoding: 'utf8' });
      strictEqual(write.status, 0, write.stderr);
      strictEqual(readFileSync(path, 'utf8'), good);
      strictEqual(spawnSync(process.execPath, [SCRIPT, '--root', root], { encoding: 'utf8' }).status, 0);
    });
  }

  it('an edit outside every region is authored text: the check stays clean and --write keeps it', () => {
    const root = repoSubsetCopy();
    const path = join(root, 'plugins/founder/commands/checkpoint.md');
    const edited = readFileSync(path, 'utf8').replace('## Completion', '## Completion\n\nAn authored note.');
    writeFileSync(path, edited);
    const check = spawnSync(process.execPath, [SCRIPT, '--root', root], { encoding: 'utf8' });
    strictEqual(check.status, 0, check.stderr);
    strictEqual(spawnSync(process.execPath, [SCRIPT, '--root', root, '--write'], { encoding: 'utf8' }).status, 0);
    strictEqual(readFileSync(path, 'utf8'), edited);
  });
});
